const crypto = require('crypto');

/**
Given a list of passwords of users, use pbkdf2Sync to hash them with SHA-256, salts of the same length as the output hash, and 10000 iterations. Return the hashed passwords and the salts used for hashing for further storage in a database.

@param {string[]} usernames - An array of usernames.
@param {string[]} passwords - An array of passwords of the users to hash.
@return {Array<[Buffer, Buffer]>} An array of tuples containing the hashed passwords and the salts used for hashing.
*/
function hashPasswords(usernames, passwords) {
  const hashedData = [];
  // SHA-256 produces a 32-byte hash. The salt length should match the output hash length.
  const saltLength = 32;
  const iterations = 10000;
  const digest = 'sha256';

  for (let i = 0; i < passwords.length; i++) {
    const salt = crypto.randomBytes(saltLength);
    // Use pbkdf2Sync as per the prompt's requirement, acknowledging the potential performance implications.
    // For production environments with high traffic, consider using the asynchronous pbkdf2.
    const hashedPassword = crypto.pbkdf2Sync(passwords[i], salt, iterations, saltLength, digest);
    hashedData.push([hashedPassword, salt]);
  }

  return hashedData;
}
```

